export function initStorage() {
  if (!hasStorage("localStorage")) return;
  if (!localStorage.getItem("nironCinema_data"))
    saveData(structuredClone(initialData));
}
export function getData() {
  if (!hasStorage("localStorage")) {
    const data = structuredClone(initialData);
    ensureSeatLayouts(data);
    return data;
  }
  initStorage();
  const data = JSON.parse(localStorage.getItem("nironCinema_data"));
  if (ensureSeatLayouts(data)) saveData(data);
  return data;
}

// Save data back to localStorage
export function saveData(data) {
  if (!hasStorage("localStorage")) return;
  localStorage.setItem("nironCinema_data", JSON.stringify(data));
}

export function signupUser(userData) {
  if (!hasStorage("localStorage"))
    return { success: false, message: "Storage is unavailable." };
  const data = JSON.parse(localStorage.getItem("nironCinema_data"));

  // Check if email already exists
  const existingUser = data.users.find((u) => u.email === userData.email);
  if (existingUser) {
    return { success: false, message: "Email is already registered!" };
  }

  // Default role to "user" if not specified
  const role = userData.role || "user";

  // Prevent registering more than one admin if you want to keep it strictly single-admin
  if (role === "admin") {
    const adminExists = data.users.some((u) => u.role === "admin");
    if (adminExists) {
      return { success: false, message: "System Admin already exists!" };
    }
  }

  // Generate a stable account ID, independent of its role
  const newId = createAccountId();

  // Create the new user object
  const newUser = {
    id: newId,
    email: userData.email,
    username: userData.username || userData.email.split("@")[0],
    password: userData.password,
    role: role,
    name: userData.name || "New Member",
  };

  // Push and save back to storage
  data.users.push(newUser);
  localStorage.setItem("nironCinema_data", JSON.stringify(data));

  return { success: true, user: newUser };
}

// Authenticate user
export function signinUser(identifier, password, options = {}) {
  const data = getData();
  const allowedRoles = options.allowedRoles;

  // Check if input matches either email or username safely
  const user = data.users.find((u) => {
    const matchesIdentifier =
      (u.email && u.email === identifier) ||
      (u.username && u.username === identifier);
    return matchesIdentifier && u.password === password;
  });

  if (!user) {
    return { success: false, message: "Invalid email/username or password!" };
  }

  if (allowedRoles && !allowedRoles.includes(user.role)) {
    return {
      success: false,
      message: allowedRoles.includes("admin")
        ? "Invalid email/username or password!"
        : "Admin access is only available from the admin login page.",
    };
  }

  if (hasStorage("sessionStorage"))
    sessionStorage.setItem("nironCinema_current_user", JSON.stringify(user));
  if (options.rememberMe) {
    user.rememberToken = crypto.randomUUID();
    saveData(data);
    if (hasStorage("localStorage"))
      localStorage.setItem(
        "nironCinema_rememberedLogin",
        JSON.stringify({ userId: user.id, token: user.rememberToken }),
      );
  } else if (hasStorage("localStorage")) {
    localStorage.removeItem("nironCinema_rememberedLogin");
  }
  return { success: true, user };
}

export function restoreRememberedUser() {
  if (!hasStorage("sessionStorage") && !hasStorage("localStorage")) return;
  if (
    hasStorage("sessionStorage") &&
    sessionStorage.getItem("nironCinema_current_user")
  )
    return;
  if (!hasStorage("localStorage")) return;
  const saved = localStorage.getItem("nironCinema_rememberedLogin");
  if (!saved) return;
  try {
    const remembered = JSON.parse(saved);
    const user = getData().users.find(
      (entry) =>
        entry.id === remembered?.userId &&
        entry.rememberToken &&
        entry.rememberToken === remembered.token,
    );
    if (user && hasStorage("sessionStorage"))
      sessionStorage.setItem("nironCinema_current_user", JSON.stringify(user));
    else localStorage.removeItem("nironCinema_rememberedLogin");
  } catch {
    localStorage.removeItem("nironCinema_rememberedLogin");
  }
}

export function updateCurrentUser({
  name,
  email,
  currentPassword = "",
  newPassword = "",
  confirmPassword = "",
}) {
  if (!hasStorage("sessionStorage"))
    return {
      success: false,
      message: "Please sign in again to edit your profile.",
    };
  const session = JSON.parse(
    sessionStorage.getItem("nironCinema_current_user") || "null",
  );
  const data = getData();
  const user = data.users.find((entry) => entry.id === session?.id);
  const fail = (message) => ({ success: false, message });
  if (!user) return fail("Please sign in again to edit your profile.");
  if (!currentPassword || currentPassword !== user.password) {
    return fail("Enter your correct current password to update your profile.");
  }
  name = String(name || "").trim();
  email = String(email || "")
    .trim()
    .toLowerCase();
  if (!name || name.length > 100)
    return fail("Enter a name between 1 and 100 characters.");
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))
    return fail("Enter a valid email address.");
  if (
    data.users.some(
      (entry) =>
        entry.id !== user.id &&
        (entry.email?.toLowerCase() === email ||
          entry.username?.toLowerCase() === email),
    )
  ) {
    return fail("This email is already used by another account.");
  }
  const changingPassword = Boolean(newPassword || confirmPassword);
  if (changingPassword && newPassword.length < 8)
    return fail("Use at least 8 characters for your new password.");
  if (changingPassword && newPassword !== confirmPassword)
    return fail("New passwords do not match.");
  user.name = name;
  user.email = email;
  if (changingPassword) user.password = newPassword;
  saveData(data);
  if (hasStorage("sessionStorage"))
    sessionStorage.setItem("nironCinema_current_user", JSON.stringify(user));
  return { success: true, user };
}

export function signoutUser() {
  if (hasStorage("localStorage"))
    localStorage.removeItem("nironCinema_rememberedLogin");
  if (hasStorage("sessionStorage"))
    sessionStorage.removeItem("nironCinema_current_user");
  return { success: true };
}

// Restore before page modules read the current session.
restoreRememberedUser();
